INSERT INTO plantillas_rutina (id, codigo, objetivo, en_casa, para_examenes, minutos, semanas, orden, lugar, nivel,
INSERT INTO plantillas_rutina_textos (plantilla_id, idioma, nombre, descripcion)
VALUES
('d8651879-02b1-5eb9-a103-c7e2e532dc94'::uuid, 'es', 'Máquinas para empezar', 'Para tu primer gimnasio: máquinas guiadas, fáciles de aprender. Empieza ligero: los pesos son para probar.'),
('d8651879-02b1-5eb9-a103-c7e2e532dc94'::uuid, 'en', 'Machines to get started', 'For your first gym: guided machines that are easy to learn. Start light: the weights are just to try.'),
('d8651879-02b1-5eb9-a103-c7e2e532dc94'::uuid, 'fr', 'Machines pour débuter', 'Pour ta première salle : des machines guidées, faciles à apprendre. Commence léger : les charges sont à essayer.'),
('d8651879-02b1-5eb9-a103-c7e2e532dc94'::uuid, 'pt', 'Máquinas para começar', 'Para o teu primeiro ginásio: máquinas guiadas, fáceis de aprender. Começa leve: os pesos são para experimentar.'),
('c66aa812-3c2a-5ceb-a006-9734204c2d60'::uuid, 'es', 'Cuerpo completo con pesas libres', 'Barra y mancuernas para aprender los movimientos básicos, cuando ya te manejas en el gimnasio. Usa el rack con los seguros puestos.'),
('c66aa812-3c2a-5ceb-a006-9734204c2d60'::uuid, 'en', 'Full body with free weights', 'Barbell and dumbbells to learn the basic lifts, once you feel at home in the gym. Use the rack with the safety bars set.'),
('c66aa812-3c2a-5ceb-a006-9734204c2d60'::uuid, 'fr', 'Corps entier avec poids libres', 'Barre et haltères pour apprendre les mouvements de base, quand tu es à l''aise en salle. Utilise le rack avec les sécurités en place.'),
('c66aa812-3c2a-5ceb-a006-9734204c2d60'::uuid, 'pt', 'Corpo inteiro com pesos livres', 'Barra e halteres para aprender os movimentos básicos, quando já te orientas no ginásio. Usa o rack com as seguranças postas.'),
('7f0da575-7730-5bc6-bde1-adfe66416b63'::uuid, 'es', 'Cuerpo completo con poco tiempo', 'Dos sesiones completas a la semana: el mínimo de fuerza que recomienda la OMS.'),
('7f0da575-7730-5bc6-bde1-adfe66416b63'::uuid, 'en', 'Full body when you''re short on time', 'Two full sessions a week: the minimum strength training the WHO recommends.'),
('7f0da575-7730-5bc6-bde1-adfe66416b63'::uuid, 'fr', 'Corps entier quand tu manques de temps', 'Deux séances complètes par semaine : le minimum de renforcement recommandé par l''OMS.'),
('7f0da575-7730-5bc6-bde1-adfe66416b63'::uuid, 'pt', 'Corpo inteiro com pouco tempo', 'Duas sessões completas por semana: o mínimo de força que a OMS recomenda.'),
('5e8720f2-02b7-5f54-9a3a-74c569dfa8e7'::uuid, 'es', 'Parte de arriba y piernas', 'Dos días de parte de arriba y dos de piernas, para quien ya entrena con constancia.'),
('5e8720f2-02b7-5f54-9a3a-74c569dfa8e7'::uuid, 'en', 'Upper body and legs', 'Two upper-body days and two leg days, for people who already train regularly.'),
('5e8720f2-02b7-5f54-9a3a-74c569dfa8e7'::uuid, 'fr', 'Haut du corps et jambes', 'Deux jours pour le haut du corps et deux pour les jambes, pour qui s''entraîne déjà régulièrement.'),
('5e8720f2-02b7-5f54-9a3a-74c569dfa8e7'::uuid, 'pt', 'Parte de cima e pernas', 'Dois dias de parte de cima e dois de pernas, para quem já treina com regularidade.'),
('1f4a688f-0763-56a1-9a44-ec844aea69e6'::uuid, 'es', 'Empujar, tirar y piernas', 'Un día para pecho, hombro y tríceps; otro para espalda y bíceps; y otro de piernas.'),
('1f4a688f-0763-56a1-9a44-ec844aea69e6'::uuid, 'en', 'Push, pull and legs', 'One day for chest, shoulders and triceps; one for back and biceps; and one for legs.'),
('1f4a688f-0763-56a1-9a44-ec844aea69e6'::uuid, 'fr', 'Pousser, tirer et jambes', 'Un jour pour pecs, épaules et triceps ; un pour le dos et les biceps ; et un pour les jambes.'),
('1f4a688f-0763-56a1-9a44-ec844aea69e6'::uuid, 'pt', 'Empurrar, puxar e pernas', 'Um dia para peito, ombros e tríceps; outro para costas e bíceps; e outro de pernas.'),
('19d4c6e5-f8a7-5734-af48-38029af68a71'::uuid, 'es', 'En casa sin material', 'Solo tu cuerpo, dos botellas de agua y una pared. Si aún no llegas a 6 flexiones, hazlas en la pared.'),
('19d4c6e5-f8a7-5734-af48-38029af68a71'::uuid, 'en', 'At home, no equipment', 'Just your body, two water bottles and a wall. If you can''t do 6 push-ups yet, do them against the wall.'),
('19d4c6e5-f8a7-5734-af48-38029af68a71'::uuid, 'fr', 'À la maison sans matériel', 'Juste ton corps, deux bouteilles d''eau et un mur. Si tu ne fais pas encore 6 pompes, fais-les contre le mur.'),
('19d4c6e5-f8a7-5734-af48-38029af68a71'::uuid, 'pt', 'Em casa sem material', 'Só o teu corpo, duas garrafas de água e uma parede. Se ainda não fazes 6 flexões, faz na parede.'),
('c0977963-e794-5132-bc51-53415b72b8f2'::uuid, 'es', 'En casa con mancuernas', 'Necesitas un par de mancuernas (mejor si son ajustables).'),
('c0977963-e794-5132-bc51-53415b72b8f2'::uuid, 'en', 'At home with dumbbells', 'You need a pair of dumbbells (adjustable ones are best).'),
('c0977963-e794-5132-bc51-53415b72b8f2'::uuid, 'fr', 'À la maison avec haltères', 'Il te faut une paire d''haltères (réglables, c''est mieux).'),
('c0977963-e794-5132-bc51-53415b72b8f2'::uuid, 'pt', 'Em casa com halteres', 'Precisas de um par de halteres (de preferência ajustáveis).'),
('d0e829fe-98e1-5201-8d4c-ecc21f83ba1f'::uuid, 'es', 'Calistenia en el parque', 'Necesitas una barra baja, una barra de dominadas, un banco y una goma elástica.'),
('d0e829fe-98e1-5201-8d4c-ecc21f83ba1f'::uuid, 'en', 'Park calisthenics', 'You need a low bar, a pull-up bar, a bench and a resistance band.'),
('d0e829fe-98e1-5201-8d4c-ecc21f83ba1f'::uuid, 'fr', 'Street workout au parc', 'Il te faut une barre basse, une barre de traction, un banc et un élastique.'),
('d0e829fe-98e1-5201-8d4c-ecc21f83ba1f'::uuid, 'pt', 'Calistenia no parque', 'Precisas de uma barra baixa, uma barra de elevações, um banco e um elástico.'),
('aec04da7-0f82-5c83-8734-b956ac703e89'::uuid, 'es', 'Mantenerte en exámenes · gimnasio', 'Media hora, dos días: mantienes lo ganado sin quitar horas de estudio. Mismo peso, menos series.'),
('aec04da7-0f82-5c83-8734-b956ac703e89'::uuid, 'en', 'Stay fit during exams · gym', 'Half an hour, two days: keep your gains without losing study time. Same weight, fewer sets.'),
('aec04da7-0f82-5c83-8734-b956ac703e89'::uuid, 'fr', 'Garder la forme en examens · salle', 'Une demi-heure, deux jours : tu gardes tes progrès sans perdre de temps de révision. Même charge, moins de séries.'),
('aec04da7-0f82-5c83-8734-b956ac703e89'::uuid, 'pt', 'Manter-te em exames · ginásio', 'Meia hora, dois dias: manténs o que ganhaste sem tirar horas de estudo. Mesmo peso, menos séries.'),
('d4ae7963-c83c-5076-87cd-aaf52aed9a8a'::uuid, 'es', 'Mantenerte en exámenes · en casa', 'Veinticinco minutos sin material, dos días, entre sesiones de estudio.'),
('d4ae7963-c83c-5076-87cd-aaf52aed9a8a'::uuid, 'en', 'Stay fit during exams · at home', 'Twenty-five minutes with no equipment, two days, between study sessions.'),
('d4ae7963-c83c-5076-87cd-aaf52aed9a8a'::uuid, 'fr', 'Garder la forme en examens · maison', 'Vingt-cinq minutes sans matériel, deux jours, entre deux révisions.'),
('d4ae7963-c83c-5076-87cd-aaf52aed9a8a'::uuid, 'pt', 'Manter-te em exames · em casa', 'Vinte e cinco minutos sem material, dois dias, entre sessões de estudo.'),
('65605e9f-3608-579f-a104-41d147321256'::uuid, 'es', 'Empieza a correr', 'De no correr nada a 30 minutos seguidos en 9 semanas, a un ritmo en el que puedas hablar. Si una semana cuesta, repítela.'),
('65605e9f-3608-579f-a104-41d147321256'::uuid, 'en', 'Start running', 'From no running at all to 30 minutes non-stop in 9 weeks, at a pace where you can still talk. If a week feels hard, repeat it.'),
('65605e9f-3608-579f-a104-41d147321256'::uuid, 'fr', 'Commence à courir', 'De zéro à 30 minutes sans t''arrêter en 9 semaines, à une allure où tu peux parler. Si une semaine est dure, refais-la.'),
('65605e9f-3608-579f-a104-41d147321256'::uuid, 'pt', 'Começa a correr', 'De não correr nada a 30 minutos seguidos em 9 semanas, a um ritmo em que consigas falar. Se uma semana custar, repete-a.'),
('13233e73-4410-56f2-9afe-c2a18a0c5579'::uuid, 'es', 'Espalda y movilidad para estudiar', 'Quince minutos para pasar muchas horas sentado sin que la espalda lo note.'),
('13233e73-4410-56f2-9afe-c2a18a0c5579'::uuid, 'en', 'Back and mobility for studying', 'Fifteen minutes so long hours sitting don''t take a toll on your back.'),
('13233e73-4410-56f2-9afe-c2a18a0c5579'::uuid, 'fr', 'Dos et mobilité pour réviser', 'Quinze minutes pour passer de longues heures assis sans que ton dos le sente.'),
('13233e73-4410-56f2-9afe-c2a18a0c5579'::uuid, 'pt', 'Costas e mobilidade para estudar', 'Quinze minutos para passares muitas horas sentado sem que as costas se ressintam.');
